ALTER TABLE items ADD COLUMN sku TEXT NOT NULL DEFAULT '';
ALTER TABLE items ADD COLUMN category TEXT NOT NULL DEFAULT '';
ALTER TABLE items ADD COLUMN brand TEXT NOT NULL DEFAULT '';
ALTER TABLE items ADD COLUMN item_kind TEXT NOT NULL DEFAULT 'product' CHECK(item_kind IN ('product','service'));
ALTER TABLE items ADD COLUMN base_unit TEXT NOT NULL DEFAULT 'قطعة';
ALTER TABLE items ADD COLUMN unit_code TEXT NOT NULL DEFAULT 'PCE';
ALTER TABLE items ADD COLUMN track_stock INTEGER NOT NULL DEFAULT 0 CHECK(track_stock IN (0,1));
ALTER TABLE items ADD COLUMN reorder_micro INTEGER NOT NULL DEFAULT 0 CHECK(reorder_micro>=0);
ALTER TABLE items ADD COLUMN purchase_cost INTEGER NOT NULL DEFAULT 0 CHECK(purchase_cost>=0);
ALTER TABLE items ADD COLUMN weight_kg TEXT NOT NULL DEFAULT '';
ALTER TABLE items ADD COLUMN volume_l TEXT NOT NULL DEFAULT '';
ALTER TABLE items ADD COLUMN length_cm TEXT NOT NULL DEFAULT '';
ALTER TABLE items ADD COLUMN width_cm TEXT NOT NULL DEFAULT '';
ALTER TABLE items ADD COLUMN height_cm TEXT NOT NULL DEFAULT '';
ALTER TABLE items ADD COLUMN size_label TEXT NOT NULL DEFAULT '';
ALTER TABLE items ADD COLUMN color TEXT NOT NULL DEFAULT '';
ALTER TABLE items ADD COLUMN notes TEXT NOT NULL DEFAULT '';
CREATE UNIQUE INDEX item_sku_unique ON items(sku) WHERE sku<>'';
CREATE TABLE warehouses(id INTEGER PRIMARY KEY,name TEXT NOT NULL UNIQUE,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)));
INSERT INTO warehouses(id,name) VALUES(1,'المستودع الرئيسي');
ALTER TABLE pos_points ADD COLUMN warehouse_id INTEGER REFERENCES warehouses(id);
UPDATE pos_points SET warehouse_id=1;
CREATE TRIGGER pos_default_warehouse AFTER INSERT ON pos_points WHEN NEW.warehouse_id IS NULL BEGIN UPDATE pos_points SET warehouse_id=1 WHERE id=NEW.id;END;
CREATE TABLE item_units(id INTEGER PRIMARY KEY,item_id INTEGER NOT NULL REFERENCES items(id),name TEXT NOT NULL,unit_code TEXT NOT NULL DEFAULT 'PCE',factor_micro INTEGER NOT NULL CHECK(factor_micro>0 AND factor_micro<=1000000000000),unit_price INTEGER NOT NULL CHECK(unit_price>=0),barcode TEXT UNIQUE,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),UNIQUE(item_id,name));
CREATE TRIGGER unit_barcode_conflict_insert BEFORE INSERT ON item_units WHEN NEW.barcode IS NOT NULL AND EXISTS(SELECT 1 FROM items WHERE barcode=NEW.barcode) BEGIN SELECT RAISE(ABORT,'الباركود مستخدم للصنف الأساسي');END;
CREATE TRIGGER unit_barcode_conflict_update BEFORE UPDATE ON item_units WHEN NEW.barcode IS NOT NULL AND EXISTS(SELECT 1 FROM items WHERE barcode=NEW.barcode) BEGIN SELECT RAISE(ABORT,'الباركود مستخدم للصنف الأساسي');END;
CREATE TRIGGER item_barcode_conflict_insert BEFORE INSERT ON items WHEN NEW.barcode IS NOT NULL AND EXISTS(SELECT 1 FROM item_units WHERE barcode=NEW.barcode) BEGIN SELECT RAISE(ABORT,'الباركود مستخدم لوحدة إضافية');END;
CREATE TRIGGER item_barcode_conflict_update BEFORE UPDATE ON items WHEN NEW.barcode IS NOT NULL AND EXISTS(SELECT 1 FROM item_units WHERE barcode=NEW.barcode) BEGIN SELECT RAISE(ABORT,'الباركود مستخدم لوحدة إضافية');END;
ALTER TABLE invoice_lines ADD COLUMN item_id INTEGER REFERENCES items(id);
ALTER TABLE invoice_lines ADD COLUMN stock_qty_micro INTEGER NOT NULL DEFAULT 0 CHECK(stock_qty_micro>=0);
ALTER TABLE invoice_lines ADD COLUMN unit_factor_micro INTEGER NOT NULL DEFAULT 1000000;
ALTER TABLE invoice_lines ADD COLUMN unit_name TEXT NOT NULL DEFAULT '';
ALTER TABLE invoice_lines ADD COLUMN warehouse_id INTEGER REFERENCES warehouses(id);
CREATE TABLE stock_movements(id INTEGER PRIMARY KEY,event_id TEXT NOT NULL,request_hash TEXT NOT NULL,item_id INTEGER NOT NULL REFERENCES items(id),warehouse_id INTEGER NOT NULL REFERENCES warehouses(id),delta_micro INTEGER NOT NULL CHECK(delta_micro<>0 AND abs(delta_micro)<=9007199254740991),kind TEXT NOT NULL CHECK(kind IN ('opening','receipt','issue','adjust_in','adjust_out','transfer_in','transfer_out','sale','return')),invoice_id INTEGER REFERENCES invoices(id),line_no INTEGER,reason TEXT NOT NULL,actor_id INTEGER,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(event_id,warehouse_id,item_id));
CREATE INDEX stock_by_item_warehouse ON stock_movements(item_id,warehouse_id,id);
CREATE UNIQUE INDEX stock_opening_once ON stock_movements(item_id,warehouse_id) WHERE kind='opening';
CREATE UNIQUE INDEX stock_invoice_line ON stock_movements(invoice_id,line_no) WHERE invoice_id IS NOT NULL;
CREATE TRIGGER stock_nonnegative BEFORE INSERT ON stock_movements WHEN COALESCE((SELECT SUM(delta_micro) FROM stock_movements WHERE item_id=NEW.item_id AND warehouse_id=NEW.warehouse_id),0)+NEW.delta_micro<0 BEGIN SELECT RAISE(ABORT,'الرصيد المخزني غير كاف في المستودع المحدد');END;
CREATE TRIGGER stock_limit BEFORE INSERT ON stock_movements WHEN COALESCE((SELECT SUM(delta_micro) FROM stock_movements WHERE item_id=NEW.item_id AND warehouse_id=NEW.warehouse_id),0)+NEW.delta_micro>9007199254740991 BEGIN SELECT RAISE(ABORT,'الرصيد أكبر من المسموح');END;
CREATE TRIGGER stock_no_update BEFORE UPDATE ON stock_movements BEGIN SELECT RAISE(ABORT,'الحركة المخزنية ثابتة؛ صحح بحركة عكسية');END;
CREATE TRIGGER stock_no_delete BEFORE DELETE ON stock_movements BEGIN SELECT RAISE(ABORT,'الحركة المخزنية ثابتة؛ صحح بحركة عكسية');END;
UPDATE local_meta SET value='5' WHERE key='schema_version';
